import Foundation
import CoreML
import Vision

public protocol ActionExecutor: Sendable {
    func openURL(_ url: URL) async -> Bool
    func executeTap(at rect: CGRect) async
}

public struct AgentRule: Codable, Sendable {
    public let triggerIdentifier: String
    public let confidenceThreshold: Float
    public let actionURL: URL?
    public let requiresTap: Bool
}

public final class AutonomousAgentOrchestrator: @unchecked Sendable {
    private let visionModel: MLModel
    private let executionQueue = DispatchQueue(label: "im.jade.agent.executor", qos: .userInitiated)
    private let executor: ActionExecutor
    private let activeRules: [AgentRule]

    public init(modelURL: URL, executor: ActionExecutor, rulesURL: URL) throws {
        let config = MLModelConfiguration()
        config.computeUnits = .all
        self.visionModel = try MLModel(contentsOf: modelURL, configuration: config)
        self.executor = executor
        let rulesData = try Data(contentsOf: rulesURL)
        self.activeRules = try JSONDecoder().decode([AgentRule].self, from: rulesData)
    }

    public func processScreenFrame(pixelBuffer: CVPixelBuffer) async throws -> AgentAction {
        return try await withCheckedThrowingContinuation { continuation in
            do {
                let coreMLModel = try VNCoreMLModel(for: visionModel)
                let request = VNCoreMLRequest(model: coreMLModel) { [weak self] request, error in
                    if let error = error {
                        continuation.resume(throwing: error)
                        return
                    }

                    guard let self = self,
                          let results = request.results as? [VNRecognizedObjectObservation],
                          let bestAction = self.inferAction(from: results) else {
                        continuation.resume(throwing: AgentError.inferenceFailed)
                        return
                    }

                    continuation.resume(returning: bestAction)
                }

                request.imageCropAndScaleOption = .scaleFit
                let handler = VNImageRequestHandler(cvPixelBuffer: pixelBuffer, options: [:])

                self.executionQueue.async {
                    do {
                        try handler.perform([request])
                    } catch {
                        continuation.resume(throwing: error)
                    }
                }
            } catch {
                continuation.resume(throwing: error)
            }
        }
    }

    private func inferAction(from observations: [VNRecognizedObjectObservation]) -> AgentAction? {
        for obs in observations {
            guard let label = obs.labels.first else { continue }
            for rule in self.activeRules {
                if label.identifier == rule.triggerIdentifier && label.confidence >= rule.confidenceThreshold {
                    if rule.requiresTap {
                        return .simulateAccessibilityTap(rect: obs.boundingBox)
                    } else if let url = rule.actionURL {
                        return .executeURLScheme(url: url)
                    }
                }
            }
        }
        return .wait(milliseconds: 500)
    }

    public func execute(action: AgentAction) async throws {
        switch action {
        case .executeURLScheme(let url):
            _ = await self.executor.openURL(url)

        case .simulateAccessibilityTap(let rect):
            await self.executor.executeTap(at: rect)

        case .wait(let ms):
            try await Task.sleep(nanoseconds: UInt64(ms * 1_000_000))
        }
    }

    public enum AgentAction: Sendable {
        case executeURLScheme(url: URL)
        case simulateAccessibilityTap(rect: CGRect)
        case wait(milliseconds: Int)
    }

    public enum AgentError: Error {
        case inferenceFailed
        case invalidRulesFormat
    }
}


